import math
from pathlib import Path
program = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    cells8 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    r0, r1 = min(r for r, c in cells8), max(r for r, c in cells8)
    c0, c1 = min(c for r, c in cells8), max(c for r, c in cells8)

    runs = []
    for r in range(r0, r1 + 1):
        c = c0
        while c <= c1:
            if grid[r][c] == 8:
                start = c
                while c <= c1 and grid[r][c] == 8:
                    c += 1
                runs.append(c - start)
            else:
                c += 1
    for c in range(c0, c1 + 1):
        r = r0
        while r <= r1:
            if grid[r][c] == 8:
                start = r
                while r <= r1 and grid[r][c] == 8:
                    r += 1
                runs.append(r - start)
            else:
                r += 1
    unit = math.gcd(*runs)
    nr, nc = (r1 - r0 + 1) // unit, (c1 - c0 + 1) // unit
    occupied = [[grid[r0 + i * unit][c0 + j * unit] == 8 for j in range(nc)] for i in range(nr)]

    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    kr0, kr1 = min(r for r, c in marks), max(r for r, c in marks)
    kc0, kc1 = min(c for r, c in marks), max(c for r, c in marks)
    key = [row[kc0:kc1 + 1] for row in grid[kr0:kr1 + 1]]

    # The color key and the tiled silhouette share a layout; turn the key to fit it.
    rotated = [list(row) for row in zip(*key[::-1])]
    if len(rotated) != nr or len(rotated[0]) != nc:
        raise ValueError("key and shape dimensions do not agree")
    if [[v != 0 for v in row] for row in rotated] != occupied:
        raise ValueError("rotated key silhouette does not match 8-shape")

    out = [row[:] for row in grid]
    for i in range(nr):
        for j in range(nc):
            if occupied[i][j]:
                color = rotated[i][j]
                for r in range(r0 + i * unit, r0 + (i + 1) * unit):
                    for c in range(c0 + j * unit, c0 + (j + 1) * unit):
                        out[r][c] = color
    return out
'''
